entries[298627] = { ["name"] = "Lebensblut", ["text"] = "Azerit Essenz\nAlle 18-25 Sek. entspringt dem Boden in der Nähe ein Lebensblutsplitter, der 18 lang bestehen bleibt.\n\nLebensblutsplitter\nDer Splitter gewährt Euch und allen anderen Verbündeten, die 'Resonanz der Weltader' verwenden, innerhalb von 8 Metern um den Splitter 13 Eures jeweiligen Primärwerts. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren." }
entries[298628] = { ["name"] = "Resonanz der Weltader", ["text"] = "Azerit Essenz\nSofort 1 min Abklingzeit\nKonzentriert Energie in das Herz von Azeroth und lässt 3 Lebensblutsplitter in der Nähe aus dem Boden schießen, die 18 Sek. lang bestehen bleiben. Erhöht außerdem den durch Lebensblutsplitter erhaltenen Primärwert 18 Sek. lang um 300%.\n\nLebensblutsplitter\nErhöht Euren Primärwert und den Primärwert jedes weiteren Verbündeten, der 'Resonanz der Weltader' benutzt, um 13 , solange Ihr Euch innerhalb von 8 Metern um den Lebensblutsplitter aufhaltet. Ihr könnt maximal von 4 Lebensblutsplittern gleichzeitig profitieren." }
