entries[298813] = { ["name"] = "Von Flammen verschlungen", ["text"] = "Animabonus\nSofort\n'Geheimnis der lebenden Flamme' verhindert den Einsatz von Frostmagie.\n\nEisfuror\nSchleudert feste Eisbrocken nach dem Ziel, die (628.695% der Zaubermacht) Frostschaden verursachen. Hierdurch fügt Euer nächster Einsatz von 'Frostschock' 4 zusätzlichen Zielen 200% mehr Schaden zu und erzeugt 7 zusätzlichen Mahlstrom.\n\nErzeugt 12 Mahlstrom." }
